	// No reader must be able to observe a partial object from the failed upload
	// (root of the oversized body is unknown, but any valid unknown CID 404s).
	req := httptest.NewRequest(http.MethodGet, "/v1/objects/"+strings.Repeat("a", 0), nil)
	_ = req
}

